function StoreEntry:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self._openId = self.controller.Argument.parameters == nil and StoreGroup[1] or self.controller.Argument.parameters.OpenId
        
        if KCookie.Get(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID) then
            self._openId = checkInt(KCookie.Get(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID))
            if self._openId == StoreConstants.OpenIds.CumulativeRecharge then
                -- 累充作为二级弹窗需要特殊处理
                self._openId = StoreConstants.OpenIds.Diamond
                self._exOpenId = StoreConstants.OpenIds.CumulativeRecharge
            end
            KCookie.Set(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID, nil)
        end
        
        if self._openId == nil or self._openId == StoreConstants.OpenIds.None then
            self._openId = StoreGroup[1]
        end
        self._exParameter = self.controller.Argument.parameters.exParameter or {}
        StoreShared:DealSettings()
        StoreShared:SetHomeGoodsIds()
        if self._exParameter.closeMainScene then
            self._exParameter.closeMainScene = nil
            self:CloseMainScene()
        end
        self:InitHandler()
        self:InitView()
        self:InitData()
        --Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    end))
    return coWait
end

function StoreEntry:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.DailyUpdateData, self._eventDailyUpdateData)
        Events.RemoveListener(Constants.EventNames.StoreEntrySwitch, self._storeEntrySwitch)
        Events.RemoveListener(Constants.EventNames.StoreDialogClose, self._storeDialogClose)
        -- self:ReleaseLoaders()
        if not isNull(self._createNodeCo) then 
            cs_coroutine.stop(self._createNodeCo)
        end
        if not isNull(self._closeCo) then
            cs_coroutine.stop(self._createNodeCo)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end
