---初始化handler
function StoreEntry:InitHandler()
    self._eventDailyUpdateData = Events.AddListener(Constants.EventNames.DailyUpdateData, Bind(self, self.RefreshEventHandler))
    self._storeEntrySwitch = Events.AddListener(Constants.EventNames.StoreEntrySwitch, Bind(self, self.SwitchEventHandler))
    self._storeDialogClose = Events.AddListener(Constants.EventNames.StoreDialogClose, Bind(self, self.CloseEventHandler))
    for i, openId in ipairs(StoreGroup) do
        local cell = self.TabListLayout:GetChild(i - 1) 
        if not isNull(cell) then
            SetButtonAction(cell, function()
                if self._openId ~= openId then
                    Events.Broadcast(Constants.EventNames.StoreEntryTabOnClick, {openId = openId})
                    self._openId = openId
                    self:EnterStore()
                end
            end)
        end
    end
end

---初始化页面
function StoreEntry:InitView()
    self:InitStoreName()
    self:InitStoreTab()
end

---初始化数据
function StoreEntry:InitData()
    GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local comp = StoreUtils.GetStoreComp()
            comp:InitialStore(response.data)

            StoreShared:StartTimer(comp)

            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_enter_one)
            self:RefreshSelf()
        end
    end)
end

---初始化页面名称
function StoreEntry:InitStoreName()
    for i, v in ipairs(StoreGroup) do
        local config = CfUtils.GetCfVo(AutoIds.IdSetting601, "StoreGeneralVo", v)
        if config then
            local cell = self.TabListLayout:GetChild(i - 1)
            local scr = CfUtils.GetLuaScr(cell, StoreEntryTabCellPath)
            if not scr then return end
            scr:RefreshName(config.tabName)
        end
    end
end

---初始化商城页签
function StoreEntry:InitStoreTab()
    if self._exParameter.hideToggle == true then
        KTool.SetActive(self.ToggleLeft, false)
        return 
    end
    
    for i, v in ipairs(StoreGroup) do
        local cell = self.TabListLayout:GetChild(i - 1)
        local root = cell:Find("AnimRoot")
        if v == StoreConstants.OpenIds.Diamond then
            if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id165) then
                GameUtils.BindRedPoint(Constants.RedPointConst.ShopAccumulativePay, root, true)
            end
        elseif v == StoreConstants.OpenIds.Gift then
            GameUtils.BindRedPoint(Constants.RedPointConst.ShopDailyGift, root, true)
        end
    end
end

---进入商店
function StoreEntry:EnterStore()
    local openId = self._openId
    if not openId then return end

    if self._createNodeCo then
        return
    end
    if self._curOpenId then
        self:RefreshTabState(self._curOpenId, false) 
        local node = self._storeNodes[tostring(self._curOpenId)]
        if not isNull(node.go) then
            KTool.SetActive(node.go, false)
            --local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
            --canvas.enabled = false
        end
    end
    
    self:RefreshTabState(openId, true)
    StoreUtils.RefreshNavigatorBar(openId)
    
    self:ShowStoreNode(openId)
end

---显示商店节点
---@param openId StoreConstants.OpenIds 商店id
function StoreEntry:ShowStoreNode(openId)
    if not openId then return end
    self:Record(openId)
    if self._storeNodes[tostring(openId)]  then
        self:RefreshStoreNode(openId)
    else
        self:CreateStoreNode(openId)
    end
    self:ShowSecondaryDialog()
end

---显示二级界面
function StoreEntry:ShowSecondaryDialog()
    if not self._exOpenId then return end

    if self._exOpenId == StoreConstants.OpenIds.CumulativeRecharge then
        UIModule.OpenDialog({ id = Constants.UITypeIds.CumulativeRechargeDialog})
    end
    self._exOpenId = nil
end

---刷新商店节点
---@param openId StoreConstants.OpenIds 商店id
function StoreEntry:RefreshStoreNode(openId)
    local node = self._storeNodes[tostring(openId)]
    if node and not isNull(node.go) and node.scr then
        KTool.SetActive(node.go, true)
        --local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
        --canvas.enabled = true
        self._exParameter.openId = openId
        node.scr:RefreshSelf(self._exParameter)
        self._curOpenId = openId
        self._exParameter = {}
    end
end

---刷新页签状态
---@param openId StoreConstants.OpenIds 商店id
---@param isSelected boolean 是否选中
function StoreEntry:RefreshTabState(openId, isSelected)
    local index = self:GetStoreTabIndex(openId)
    if not index then return end
    
    local cell = self.TabListLayout:GetChild(index - 1)
    local scr = CfUtils.GetLuaScr(cell, StoreEntryTabCellPath)
    if not scr then return end
    scr:RefreshCellState(isSelected)
end

---获取商店页签序号
---@param openId StoreConstants.OpenIds 
function StoreEntry:GetStoreTabIndex(openId)
    for i, v in ipairs(StoreGroup) do
        if checkInt(openId) == v then
            return i
        end
    end
end

