---创建一个商店页面
---@param openId integer 商店id
---@return userdata
function StoreEntry:CreateStoreNode(openId)
    self._createNodeCo = cs_coroutine.start(function()
        local config = StoreConstants.Config[openId]
        local go = GameUtils.LoadBundleAsyncById(config.prefabId, self.StoreNodeGroup.gameObject, false, true)
        local scr = CfUtils.GetLuaScr(go, config.scrPath)
        -- self:AddLoader(loader)
        local node = {
            go = go,
            scr = scr,
        }
        self._storeNodes[tostring(openId)] = node
        self:RefreshStoreNode(openId)
        self._createNodeCo = nil
    end)
end

