function StoreEntry:RefreshEventHandler()
    GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local comp = StoreUtils.GetStoreComp()
            comp:InitialStore(response.data)
            self:RefreshSelf()
        end
    end)
end

function StoreEntry:SwitchEventHandler(parameters)
    self._openId = parameters.openId
    self._exParameter = parameters.exParameter or {}
    self:RefreshSelf()
end

function StoreEntry:CloseEventHandler()
    UIModule.CloseDialog(self.controller)
end

function StoreEntry:Record(openId)
    if openId == StoreConstants.OpenIds.Recommendation then
        xRecord.record('9-002')
    elseif openId == StoreConstants.OpenIds.Diamond then
        xRecord.record('9-003')
    elseif openId == StoreConstants.OpenIds.Gift then
        xRecord.record('9-005')
    elseif openId == StoreConstants.OpenIds.MonthlyMembership then
        xRecord.record('9-006')
    elseif openId == StoreConstants.OpenIds.Supply then
        xRecord.record('9-007')
    elseif openId == StoreConstants.OpenIds.LevelGift then
        xRecord.record('9-020')
    end
end

---关闭主场景
function StoreEntry:CloseMainScene()
    self._closeCo = cs_coroutine.start(function ()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        CS.UINavigationBarRoot.Instance:SetActive(true)
        UIRaycastBlocker:RemoveCondition("OpenDialogAction")
        KCookie.Set(Constants.IsOpnePageing, 0)
        self._closeCo = nil
    end)
end
